 const initial=alphabetJumpInput.value.trim().toLocaleUpperCase(language==="fi"?"fi":"en");
 const isNumber=/^\d$/.test(initial);
 const isLetter=/^[A-Z]$/i.test(initial);
 if(!isNumber&&!isLetter)return;
 sortSelect.value="title";
