// 8. Accessible hamburger navigation and compact tab views.
(() => {
 const toggle=document.getElementById("menu-toggle");
 const menu=document.getElementById("vault-navigation");
 const tabs=[...document.querySelectorAll("[data-tab-target]")];
 const panels=[...document.querySelectorAll("[data-tab-panel]")];
 if(!toggle||!menu||!panels.length)return;
 const closeMenu=()=>{menu.hidden=true;toggle.setAttribute("aria-expanded","false");};
 const activate=(name)=>{
  panels.forEach(panel=>{const active=panel.dataset.tabPanel===name;panel.hidden=!active;panel.classList.toggle("is-active",active);});
  tabs.forEach(tab=>{const active=tab.dataset.tabTarget===name;tab.classList.toggle("is-active",active);if(tab.tagName==="BUTTON")tab.setAttribute("aria-current",active?"page":"false");});
  closeMenu();
  window.scrollTo({top:0,behavior:window.matchMedia("(prefers-reduced-motion: reduce)").matches?"auto":"smooth"});
 };
 toggle.addEventListener("click",()=>{const opening=menu.hidden;menu.hidden=!opening;toggle.setAttribute("aria-expanded",String(opening));});
 tabs.forEach(tab=>tab.addEventListener("click",event=>{if(tab.tagName==="A")event.preventDefault();activate(tab.dataset.tabTarget);}));
 document.addEventListener("click",event=>{if(!menu.hidden&&!menu.contains(event.target)&&!toggle.contains(event.target))closeMenu();});
 document.addEventListener("keydown",event=>{if(event.key==="Escape"&&!menu.hidden){closeMenu();toggle.focus();}});
})();
